  "After the {{trial}}, {{price}} per year is charged to your Apple Account and renews automatically unless cancelled at least 24 hours before the end of the period.": "{{trial}} ਤੋਂ ਬਾਅਦ, {{price}} ਪ੍ਰਤੀ ਸਾਲ ਤੁਹਾਡੇ Apple ਖਾਤੇ ਤੋਂ ਲਿਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਆਪਣੇ-ਆਪ ਰੀਨਿਊ ਹੁੰਦਾ ਹੈ, ਜਦੋਂ ਤੱਕ ਮਿਆਦ ਖ਼ਤਮ ਹੋਣ ਤੋਂ ਘੱਟੋ-ਘੱਟ 24 ਘੰਟੇ ਪਹਿਲਾਂ ਰੱਦ ਨਾ ਕੀਤਾ ਜਾਵੇ।",
