  "Couldn’t find where you are right now. Type the address instead.": "ਤੁਸੀਂ ਹੁਣ ਕਿੱਥੇ ਹੋ, ਇਹ ਪਤਾ ਨਹੀਂ ਲੱਗ ਸਕਿਆ। ਇਸਦੀ ਬਜਾਏ ਪਤਾ ਟਾਈਪ ਕਰੋ।",
