  "Couldn’t reach the App Store. Check your connection and try again.": "App Store ਨਾਲ ਸੰਪਰਕ ਨਹੀਂ ਹੋ ਸਕਿਆ। ਆਪਣਾ ਕਨੈਕਸ਼ਨ ਚੈੱਕ ਕਰੋ ਅਤੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "Couldn’t save the place. Please try again.": "ਥਾਂ ਸੇਵ ਨਹੀਂ ਹੋ ਸਕੀ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "Country": "ਦੇਸ਼",
  "CRA asks for a logbook showing the date, destination, purpose and kilometres of each business trip, plus your odometer readings at the start and end of the year.": "CRA ਇੱਕ ਲੌਗਬੁੱਕ ਮੰਗਦਾ ਹੈ ਜਿਸ ਵਿੱਚ ਹਰ ਬਿਜ਼ਨਸ ਟ੍ਰਿਪ ਦੀ ਤਾਰੀਖ਼, ਮੰਜ਼ਿਲ, ਮਕਸਦ ਅਤੇ ਕਿਲੋਮੀਟਰ ਹੋਣ, ਨਾਲ ਹੀ ਸਾਲ ਦੀ ਸ਼ੁਰੂਆਤ ਅਤੇ ਅੰਤ ’ਤੇ ਤੁਹਾਡੀ ਓਡੋਮੀਟਰ ਰੀਡਿੰਗ।",
  "CRA needs your total distance driven to work out your business-use share.": "ਤੁਹਾਡਾ ਬਿਜ਼ਨਸ-ਵਰਤੋਂ ਵਾਲਾ ਹਿੱਸਾ ਕੱਢਣ ਲਈ CRA ਨੂੰ ਤੁਹਾਡੀ ਕੁੱਲ ਚਲਾਈ ਦੂਰੀ ਚਾਹੀਦੀ ਹੈ।",
  "CRA per-km rate: 73¢ for the first 5,000 km, then 67¢": "CRA ਪ੍ਰਤੀ ਕਿ.ਮੀ. ਰੇਟ: ਪਹਿਲੇ 5,000 ਕਿ.ਮੀ. ਲਈ 73¢, ਫਿਰ 67¢",
  "Create PDF report": "PDF ਰਿਪੋਰਟ ਬਣਾਓ",
  "Date": "ਤਾਰੀਖ਼",
