  "Date: {{date}}. Show calendar": "ਤਾਰੀਖ਼: {{date}}। ਕੈਲੰਡਰ ਦਿਖਾਓ",
  "Dates are a guide; deadlines can move for weekends and holidays. Check with {{authority}} or your accountant. Not tax advice.": "ਤਾਰੀਖ਼ਾਂ ਸਿਰਫ਼ ਅੰਦਾਜ਼ੇ ਲਈ ਹਨ; ਵੀਕਐਂਡ ਅਤੇ ਛੁੱਟੀਆਂ ਕਰਕੇ ਆਖ਼ਰੀ ਤਾਰੀਖ਼ਾਂ ਬਦਲ ਸਕਦੀਆਂ ਹਨ। {{authority}} ਜਾਂ ਆਪਣੇ ਅਕਾਊਂਟੈਂਟ ਤੋਂ ਪੁੱਛ ਲਓ। ਇਹ ਟੈਕਸ ਸਲਾਹ ਨਹੀਂ ਹੈ।",
