  "Delete trip?": "ਟ੍ਰਿਪ ਮਿਟਾਉਣਾ ਹੈ?",
  "Delivery apps only count km with an order on board. The drive to the pickup, between orders and home again are work km too, and MileSprout logs them all.": "ਡਿਲੀਵਰੀ ਐਪਾਂ ਸਿਰਫ਼ ਉਹ ਕਿ.ਮੀ. ਗਿਣਦੀਆਂ ਹਨ ਜਦੋਂ ਆਰਡਰ ਨਾਲ ਹੋਵੇ। ਪਿਕਅੱਪ ਤੱਕ ਜਾਣਾ, ਇੱਕ ਆਰਡਰ ਤੋਂ ਦੂਜੇ ਤੱਕ ਜਾਣਾ ਅਤੇ ਵਾਪਸ ਘਰ ਆਉਣਾ ਵੀ ਕੰਮ ਦੇ ਕਿ.ਮੀ. ਹਨ, ਅਤੇ MileSprout ਇਹ ਸਾਰੇ ਦਰਜ ਕਰਦਾ ਹੈ।",
  "Delivery apps only count miles with an order on board. The drive to the pickup, between orders and home again are work miles too, and MileSprout logs them all.": "ਡਿਲੀਵਰੀ ਐਪਾਂ ਸਿਰਫ਼ ਉਹ ਮੀਲ ਗਿਣਦੀਆਂ ਹਨ ਜਦੋਂ ਆਰਡਰ ਨਾਲ ਹੋਵੇ। ਪਿਕਅੱਪ ਤੱਕ ਜਾਣਾ, ਇੱਕ ਆਰਡਰ ਤੋਂ ਦੂਜੇ ਤੱਕ ਜਾਣਾ ਅਤੇ ਵਾਪਸ ਘਰ ਆਉਣਾ ਵੀ ਕੰਮ ਦੇ ਮੀਲ ਹਨ, ਅਤੇ MileSprout ਇਹ ਸਾਰੇ ਦਰਜ ਕਰਦਾ ਹੈ।",
  "Delivery or collection": "ਡਿਲੀਵਰੀ ਜਾਂ ਪਿਕਅੱਪ",
  "Done": "ਹੋ ਗਿਆ",
  "Drives are logged when you park.": "ਗੱਡੀ ਪਾਰਕ ਕਰਦੇ ਹੀ ਟ੍ਰਿਪ ਦਰਜ ਹੋ ਜਾਂਦੇ ਹਨ।",
  "Drives may be missed": "ਟ੍ਰਿਪ ਛੁੱਟ ਸਕਦੇ ਹਨ",
  "Drives that start during your hours are marked work, others personal. Your usual routes and commutes take priority.": "ਤੁਹਾਡੇ ਕੰਮ ਦੇ ਘੰਟਿਆਂ ਵਿੱਚ ਸ਼ੁਰੂ ਹੋਣ ਵਾਲੇ ਟ੍ਰਿਪ ਕੰਮ ਦੇ ਮੰਨੇ ਜਾਂਦੇ ਹਨ, ਬਾਕੀ ਨਿੱਜੀ। ਤੁਹਾਡੇ ਆਮ ਰਸਤਿਆਂ ਅਤੇ ਘਰ-ਕੰਮ ਆਉਣ-ਜਾਣ ਨੂੰ ਪਹਿਲ ਮਿਲਦੀ ਹੈ।",
  "Driving {{vehicle}}. Change vehicle": "ਗੱਡੀ: {{vehicle}}। ਗੱਡੀ ਬਦਲੋ",
  "Driving now": "ਹੁਣ ਵਰਤੋਂ ਵਿੱਚ",
  "Driving:": "ਗੱਡੀ:",
  "Due {{date}}. Your mileage report for {{year}} is ready to export.": "ਆਖ਼ਰੀ ਤਾਰੀਖ਼ {{date}}। {{year}} ਲਈ ਤੁਹਾਡੀ ਮਾਈਲੇਜ ਰਿਪੋਰਟ ਐਕਸਪੋਰਟ ਲਈ ਤਿਆਰ ਹੈ।",
  "e.g. Quote for Acme Ltd": "ਜਿਵੇਂ Acme Ltd ਲਈ ਕੋਟੇਸ਼ਨ",
  "Edit this vehicle": "ਇਹ ਗੱਡੀ ਐਡਿਟ ਕਰੋ",
  "Employees reimbursed at CRA’s per-km rate: the figure above is what your employer can pay you tax-free.": "CRA ਦੇ ਪ੍ਰਤੀ ਕਿ.ਮੀ. ਰੇਟ ’ਤੇ ਪੈਸੇ ਵਾਪਸ ਲੈਣ ਵਾਲੇ ਮੁਲਾਜ਼ਮ: ਉੱਪਰ ਦਿੱਤੀ ਰਕਮ ਤੁਹਾਡਾ ਇੰਪਲਾਇਰ ਤੁਹਾਨੂੰ ਟੈਕਸ-ਮੁਕਤ ਦੇ ਸਕਦਾ ਹੈ।",
  "Employees: claim work-related car expenses at D1 on your return, up to 5,000 km per car with the cents per km method.": "ਮੁਲਾਜ਼ਮ: ਆਪਣੀ ਰਿਟਰਨ ਵਿੱਚ D1 ’ਤੇ ਕੰਮ ਨਾਲ ਜੁੜੇ ਕਾਰ ਖ਼ਰਚੇ ਕਲੇਮ ਕਰੋ, cents per km method ਨਾਲ ਹਰ ਕਾਰ ਲਈ 5,000 ਕਿ.ਮੀ. ਤੱਕ।",
  "Employees: if your employer pays less than 55p a mile (or nothing), claim the difference with form P87 or on Self Assessment. You can go back 4 tax years.": "ਮੁਲਾਜ਼ਮ: ਜੇ ਤੁਹਾਡਾ ਇੰਪਲਾਇਰ ਪ੍ਰਤੀ ਮੀਲ 55p ਤੋਂ ਘੱਟ ਦਿੰਦਾ ਹੈ (ਜਾਂ ਕੁਝ ਨਹੀਂ), ਤਾਂ ਫ਼ਰਕ form P87 ਨਾਲ ਜਾਂ Self Assessment ਵਿੱਚ ਕਲੇਮ ਕਰੋ। 4 ਟੈਕਸ ਸਾਲ ਪਿੱਛੇ ਤੱਕ ਦਾ ਕਲੇਮ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।",
  "Employees: unreimbursed mileage can’t be deducted on your federal return. Use your log to get paid back by your employer; a few states still allow a deduction.": "ਮੁਲਾਜ਼ਮ: ਜਿਸ ਮਾਈਲੇਜ ਦੇ ਪੈਸੇ ਵਾਪਸ ਨਹੀਂ ਮਿਲੇ, ਉਸਦੀ ਕਟੌਤੀ ਫ਼ੈਡਰਲ ਰਿਟਰਨ ਵਿੱਚ ਨਹੀਂ ਲਈ ਜਾ ਸਕਦੀ। ਆਪਣੇ ਲੌਗ ਨਾਲ ਆਪਣੇ ਇੰਪਲਾਇਰ ਤੋਂ ਪੈਸੇ ਵਾਪਸ ਲਓ; ਕੁਝ ਸਟੇਟਾਂ ਹਾਲੇ ਵੀ ਕਟੌਤੀ ਦੀ ਇਜਾਜ਼ਤ ਦਿੰਦੀਆਂ ਹਨ।",
  "Employees: with a signed T2200 from your employer, claim vehicle expenses on form T777. Otherwise, use your log to get reimbursed at the per-km rate.": "ਮੁਲਾਜ਼ਮ: ਜੇ ਤੁਹਾਡੇ ਇੰਪਲਾਇਰ ਨੇ T2200 ’ਤੇ ਦਸਤਖ਼ਤ ਕਰਕੇ ਦਿੱਤਾ ਹੈ, ਤਾਂ form T777 ’ਤੇ ਗੱਡੀ ਦੇ ਖ਼ਰਚੇ ਕਲੇਮ ਕਰੋ। ਨਹੀਂ ਤਾਂ, ਆਪਣੇ ਲੌਗ ਨਾਲ ਪ੍ਰਤੀ ਕਿ.ਮੀ. ਰੇਟ ’ਤੇ ਪੈਸੇ ਵਾਪਸ ਲਓ।",
  "Employees: you can claim Mileage Allowance Relief on the difference between this total and any mileage allowance your employer paid you.": "ਮੁਲਾਜ਼ਮ: ਇਸ ਕੁੱਲ ਰਕਮ ਅਤੇ ਤੁਹਾਡੇ ਇੰਪਲਾਇਰ ਵੱਲੋਂ ਦਿੱਤੇ ਮਾਈਲੇਜ ਭੱਤੇ ਦੇ ਫ਼ਰਕ ’ਤੇ Mileage Allowance Relief ਕਲੇਮ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।",
  "Encrypted on your iPhone, no ads": "ਤੁਹਾਡੇ iPhone ’ਤੇ ਇਨਕ੍ਰਿਪਟਡ, ਕੋਈ ਇਸ਼ਤਿਹਾਰ ਨਹੀਂ",
