  "Enter odometer readings as numbers, e.g. 48210.": "ਓਡੋਮੀਟਰ ਰੀਡਿੰਗ ਅੰਕਾਂ ਵਿੱਚ ਭਰੋ, ਜਿਵੇਂ 48210।",
