  "Estimated tax: if you expect to owe $1,000 or more, pay quarterly with Form 1040-ES by April 15, June 15, September 15 and January 15. Your mileage lowers your profit, so keep it up to date to avoid overpaying.": "Estimated tax (ਅੰਦਾਜ਼ਨ ਟੈਕਸ): ਜੇ ਤੁਹਾਡਾ $1,000 ਜਾਂ ਵੱਧ ਟੈਕਸ ਬਣਨ ਦੀ ਉਮੀਦ ਹੈ, ਤਾਂ Form 1040-ES ਨਾਲ ਹਰ ਤਿਮਾਹੀ 15 ਅਪ੍ਰੈਲ, 15 ਜੂਨ, 15 ਸਤੰਬਰ ਅਤੇ 15 ਜਨਵਰੀ ਤੱਕ ਭਰੋ। ਤੁਹਾਡੀ ਮਾਈਲੇਜ ਤੁਹਾਡਾ ਮੁਨਾਫ਼ਾ ਘਟਾਉਂਦੀ ਹੈ, ਇਸ ਲਈ ਵੱਧ ਭਰਨ ਤੋਂ ਬਚਣ ਲਈ ਇਸਨੂੰ ਅੱਪ-ਟੂ-ਡੇਟ ਰੱਖੋ।",
