  "In Settings, under Allow Location Access, choose Always": "ਸੈਟਿੰਗਾਂ ਵਿੱਚ, “ਟਿਕਾਣੇ ਤੱਕ ਪਹੁੰਚ ਦੀ ਇਜਾਜ਼ਤ ਦਿਓ” ਹੇਠਾਂ “ਹਮੇਸ਼ਾਂ” ਚੁਣੋ",
  "Included": "ਸ਼ਾਮਲ ਹੈ",
  "Includes {{amount}} from home ↔ work commutes, which usually aren’t deductible.": "ਇਸ ਵਿੱਚ ਘਰ ↔ ਕੰਮ ਆਉਣ-ਜਾਣ ਦੇ {{amount}} ਸ਼ਾਮਲ ਹਨ, ਜੋ ਆਮ ਤੌਰ ’ਤੇ ਕਟੌਤੀ ਵਿੱਚ ਨਹੀਂ ਆਉਂਦੇ।",
  "Individuals: enter the deduction as Work-related car expenses (D1) using the cents per km method. Sole traders: include it with your business motor vehicle expenses.": "ਵਿਅਕਤੀ: cents per km method ਵਰਤ ਕੇ ਕਟੌਤੀ Work-related car expenses (D1) ਵਜੋਂ ਭਰੋ। Sole traders (ਇਕੱਲੇ ਕਾਰੋਬਾਰੀ): ਇਸਨੂੰ ਆਪਣੇ ਬਿਜ਼ਨਸ ਮੋਟਰ ਵਾਹਨ ਖ਼ਰਚਿਆਂ ਵਿੱਚ ਸ਼ਾਮਲ ਕਰੋ।",
  "Instalments: if your net tax owing is over $3,000 ($1,800 in Quebec), CRA asks for quarterly payments by March 15, June 15, September 15 and December 15.": "ਕਿਸ਼ਤਾਂ: ਜੇ ਤੁਹਾਡਾ ਬਣਦਾ ਨੈੱਟ ਟੈਕਸ $3,000 ਤੋਂ ਵੱਧ ਹੈ (Quebec ਵਿੱਚ $1,800), ਤਾਂ CRA 15 ਮਾਰਚ, 15 ਜੂਨ, 15 ਸਤੰਬਰ ਅਤੇ 15 ਦਸੰਬਰ ਤੱਕ ਤਿਮਾਹੀ ਭੁਗਤਾਨ ਮੰਗਦਾ ਹੈ।",
  "iOS asks twice. Tap <b>Allow While Using App</b>, then <b>Change to Always Allow</b>.": "iOS ਦੋ ਵਾਰ ਪੁੱਛਦਾ ਹੈ। <b>ਐਪ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ ਇਜਾਜ਼ਤ ਦਿਓ</b> ’ਤੇ ਟੈਪ ਕਰੋ, ਫਿਰ <b>ਹਮੇਸ਼ਾਂ ਇਜਾਜ਼ਤ ਦੇਣ ’ਤੇ ਬਦਲੋ</b> ’ਤੇ।",
  "iOS only offers “Always” in Settings. It takes ten seconds, and MileSprout continues by itself when you come back.": "iOS “ਹਮੇਸ਼ਾਂ” ਸਿਰਫ਼ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਦਿੰਦਾ ਹੈ। ਬੱਸ ਦਸ ਸਕਿੰਟ ਲੱਗਦੇ ਹਨ, ਅਤੇ ਵਾਪਸ ਆਉਣ ’ਤੇ MileSprout ਆਪਣੇ-ਆਪ ਅੱਗੇ ਚੱਲ ਪੈਂਦਾ ਹੈ।",
  "IRS standard mileage rate: 76¢ a mile from July 2026": "IRS ਸਟੈਂਡਰਡ ਮਾਈਲੇਜ ਰੇਟ: ਜੁਲਾਈ 2026 ਤੋਂ 76¢ ਪ੍ਰਤੀ ਮੀਲ",
  "Keep going": "ਲੱਗੇ ਰਹੋ",
