  "Kilometres your delivery app counted": "ਤੁਹਾਡੀ ਡਿਲੀਵਰੀ ਐਪ ਵੱਲੋਂ ਗਿਣੇ ਕਿਲੋਮੀਟਰ",
  "km": "ਕਿ.ਮੀ.",
  "km your delivery app counted": "ਤੁਹਾਡੀ ਡਿਲੀਵਰੀ ਐਪ ਵੱਲੋਂ ਗਿਣੇ ਕਿ.ਮੀ.",
  "A quick question 🙋": "ਇੱਕ ਛੋਟਾ ਜਿਹਾ ਸਵਾਲ 🙋",
  "Language": "ਭਾਸ਼ਾ",
  "Language: {{name}}. Change": "ਭਾਸ਼ਾ: {{name}}। ਬਦਲੋ",
  "Last chance: make sure every work drive is in MileSprout before {{date}}.": "ਆਖ਼ਰੀ ਰਿਮਾਈਂਡਰ: {{date}} ਤੋਂ ਪਹਿਲਾਂ ਪੱਕਾ ਕਰੋ ਕਿ ਕੰਮ ਦਾ ਹਰ ਟ੍ਰਿਪ MileSprout ਵਿੱਚ ਹੈ।",
  "Last day of the {{year}} tax year": "{{year}} ਟੈਕਸ ਸਾਲ ਦਾ ਆਖ਼ਰੀ ਦਿਨ",
