  "Let’s do this! 💪": "ਚੱਲੋ, ਕਰ ਦਿਖਾਈਏ! 💪",
  "Let’s go! 🚀": "ਚੱਲੋ ਚੱਲੀਏ! 🚀",
  "Uses little battery": "ਘੱਟ ਬੈਟਰੀ ਖਾਂਦਾ",
  "Take a minute to sort this week’s drives.": "ਇੱਕ ਮਿੰਟ ਕੱਢ ਕੇ ਇਸ ਹਫ਼ਤੇ ਦੇ ਟ੍ਰਿਪ ਛਾਂਟ ਲਓ।",
  "Location is off for MileSprout, so type the address instead.": "MileSprout ਲਈ ਟਿਕਾਣਾ ਬੰਦ ਹੈ, ਇਸ ਲਈ ਪਤਾ ਟਾਈਪ ਕਰੋ।",
  "Location is set to “While Using”. Switch it to “Always” so drives are logged when the app is closed.": "ਟਿਕਾਣਾ “ਐਪ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ” ’ਤੇ ਹੈ। ਇਸਨੂੰ “ਹਮੇਸ਼ਾਂ” ’ਤੇ ਕਰੋ ਤਾਂ ਜੋ ਐਪ ਬੰਦ ਹੋਣ ’ਤੇ ਵੀ ਟ੍ਰਿਪ ਦਰਜ ਹੋਣ।",
  "Log every drive automatically": "ਹਰ ਟ੍ਰਿਪ ਆਪਣੇ-ਆਪ ਦਰਜ ਕਰੋ",
  "It only takes a minute ⏱️": "ਬੱਸ ਇੱਕ ਮਿੰਟ ਲੱਗਦਾ ਹੈ ⏱️",
  "Making Tax Digital: if your self-employed and property income is over £50,000 (£30,000 from April 2027, £20,000 from April 2028), you also send quarterly updates through MTD software by 7 August, 7 November, 7 February and 7 May. Your mileage counts towards each update.": "Making Tax Digital: ਜੇ ਤੁਹਾਡੀ ਸਵੈ-ਰੁਜ਼ਗਾਰ ਅਤੇ ਪ੍ਰਾਪਰਟੀ ਦੀ ਆਮਦਨ £50,000 ਤੋਂ ਵੱਧ ਹੈ (ਅਪ੍ਰੈਲ 2027 ਤੋਂ £30,000, ਅਪ੍ਰੈਲ 2028 ਤੋਂ £20,000), ਤਾਂ MTD ਸਾਫ਼ਟਵੇਅਰ ਰਾਹੀਂ 7 ਅਗਸਤ, 7 ਨਵੰਬਰ, 7 ਫ਼ਰਵਰੀ ਅਤੇ 7 ਮਈ ਤੱਕ ਤਿਮਾਹੀ ਅੱਪਡੇਟ ਵੀ ਭੇਜਣੇ ਹੁੰਦੇ ਹਨ। ਤੁਹਾਡੀ ਮਾਈਲੇਜ ਹਰ ਅੱਪਡੇਟ ਵਿੱਚ ਗਿਣੀ ਜਾਂਦੀ ਹੈ।",
  "Manage or cancel anytime in your App Store account settings.": "ਆਪਣੀਆਂ App Store ਖਾਤਾ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਜਦੋਂ ਮਰਜ਼ੀ ਬਦਲੋ ਜਾਂ ਰੱਦ ਕਰੋ।",
  "Manage subscription": "ਸਬਸਕ੍ਰਿਪਸ਼ਨ ਸੰਭਾਲੋ",
  "Map of this drive": "ਇਸ ਟ੍ਰਿਪ ਦਾ ਨਕਸ਼ਾ",
  "Mark {{from}} to {{to}} as work": "{{from}} ਤੋਂ {{to}} ਨੂੰ ਕੰਮ ਦਾ ਮਾਰਕ ਕਰੋ",
  "Mark {{from}} to {{to}} as personal": "{{from}} ਤੋਂ {{to}} ਨੂੰ ਨਿੱਜੀ ਮਾਰਕ ਕਰੋ",
  "Measuring the route…": "ਰਸਤਾ ਮਾਪ ਰਹੇ ਹਾਂ…",
  "MileSprout couldn’t open this screen. Your trips are safe. Please send a screenshot of this page to {{email}} so we can fix it.": "MileSprout ਇਹ ਸਕ੍ਰੀਨ ਨਹੀਂ ਖੋਲ੍ਹ ਸਕਿਆ। ਤੁਹਾਡੇ ਟ੍ਰਿਪ ਸੁਰੱਖਿਅਤ ਹਨ। ਕਿਰਪਾ ਕਰਕੇ ਇਸ ਪੰਨੇ ਦਾ ਸਕ੍ਰੀਨਸ਼ਾਟ {{email}} ’ਤੇ ਭੇਜੋ ਤਾਂ ਜੋ ਅਸੀਂ ਇਸਨੂੰ ਠੀਕ ਕਰ ਸਕੀਏ।",
  "MileSprout has now found {{amount}} in work mileage for you. That’s your hard work, counted.": "MileSprout ਨੇ ਹੁਣ ਤੱਕ ਤੁਹਾਡੇ ਲਈ {{amount}} ਦੀ ਕੰਮ ਦੀ ਮਾਈਲੇਜ ਲੱਭੀ ਹੈ। ਤੁਹਾਡੀ ਮਿਹਨਤ ਦਾ ਪੂਰਾ ਹਿਸਾਬ।",
  "MileSprout has now found {{amount}} in work mileage for you. Well done. Keep going.": "MileSprout ਨੇ ਹੁਣ ਤੱਕ ਤੁਹਾਡੇ ਲਈ {{amount}} ਦੀ ਕੰਮ ਦੀ ਮਾਈਲੇਜ ਲੱਭੀ ਹੈ। ਬਹੁਤ ਵਧੀਆ। ਇੰਝ ਹੀ ਚੱਲਦੇ ਰਹੋ।",
  "MileSprout has now found {{amount}} in work mileage for you. It all counts at tax time.": "MileSprout ਨੇ ਹੁਣ ਤੱਕ ਤੁਹਾਡੇ ਲਈ {{amount}} ਦੀ ਕੰਮ ਦੀ ਮਾਈਲੇਜ ਲੱਭੀ ਹੈ। ਟੈਕਸ ਵੇਲੇ ਇਹ ਸਭ ਕੰਮ ਆਉਂਦਾ ਹੈ।",
  "MileSprout has now found {{amount}} in work mileage for you. You earned all of it.": "MileSprout ਨੇ ਹੁਣ ਤੱਕ ਤੁਹਾਡੇ ਲਈ {{amount}} ਦੀ ਕੰਮ ਦੀ ਮਾਈਲੇਜ ਲੱਭੀ ਹੈ। ਇਹ ਸਾਰਾ ਤੁਹਾਡੀ ਮਿਹਨਤ ਦਾ ਹੈ।",
  "MileSprout hit a problem": "MileSprout ਨੂੰ ਕੋਈ ਦਿੱਕਤ ਆ ਗਈ",
  "MileSprout is logging this drive": "MileSprout ਇਹ ਟ੍ਰਿਪ ਦਰਜ ਕਰ ਰਿਹਾ ਹੈ",
  "MileSprout logs your drives for you. Just drive.": "MileSprout ਤੁਹਾਡੇ ਟ੍ਰਿਪ ਆਪੇ ਰਿਕਾਰਡ ਕਰਦਾ ਹੈ। ਤੁਸੀਂ ਬੱਸ ਗੱਡੀ ਚਲਾਓ।",
  "MileSprout logged": "MileSprout ਨੇ ਦਰਜ ਕੀਤੇ",
  "MileSprout logs your drives automatically and works out what they’re worth at tax time.": "MileSprout ਤੁਹਾਡੇ ਟ੍ਰਿਪ ਆਪਣੇ-ਆਪ ਦਰਜ ਕਰਦਾ ਹੈ ਅਤੇ ਹਿਸਾਬ ਲਾਉਂਦਾ ਹੈ ਕਿ ਟੈਕਸ ਵੇਲੇ ਉਨ੍ਹਾਂ ਦੀ ਕਿੰਨੀ ਕੀਮਤ ਹੈ।",
  "MileSprout needs location access set to “Always” to notice when you start driving, even when the app is closed.": "ਡਰਾਈਵਿੰਗ ਕਦੋਂ ਸ਼ੁਰੂ ਹੁੰਦੀ ਹੈ, ਇਹ ਪਤਾ ਲਾਉਣ ਲਈ MileSprout ਨੂੰ ਟਿਕਾਣੇ ਦੀ ਇਜਾਜ਼ਤ “ਹਮੇਸ਼ਾਂ” ’ਤੇ ਚਾਹੀਦੀ ਹੈ, ਐਪ ਬੰਦ ਹੋਣ ’ਤੇ ਵੀ।",
  "MileSprout Pro is active": "MileSprout Pro ਚਾਲੂ ਹੈ",
  "MileSprout Pro restored": "MileSprout Pro ਬਹਾਲ ਹੋ ਗਿਆ",
  "MileSprout sorts your drives to match. You can always swipe to change a trip.": "MileSprout ਤੁਹਾਡੇ ਟ੍ਰਿਪ ਉਸੇ ਹਿਸਾਬ ਨਾਲ ਛਾਂਟਦਾ ਹੈ। ਕੋਈ ਟ੍ਰਿਪ ਬਦਲਣਾ ਹੋਵੇ, ਤਾਂ ਕਦੇ ਵੀ ਸਵਾਈਪ ਕਰੋ।",
  "MileSprout uses your country’s currency, distance unit, tax year and official mileage rate.": "MileSprout ਚੁਣੇ ਹੋਏ ਦੇਸ਼ ਦੀ ਕਰੰਸੀ, ਦੂਰੀ ਦੀ ਇਕਾਈ, ਟੈਕਸ ਸਾਲ ਅਤੇ ਸਰਕਾਰੀ ਮਾਈਲੇਜ ਰੇਟ ਵਰਤਦਾ ਹੈ।",
  "MileSprout. Tap to skip": "MileSprout। ਛੱਡਣ ਲਈ ਟੈਪ ਕਰੋ",
