  "My delivery app counted {{counted}} km last month. MileSprout logged {{logged}} work km: that's {{extra}} km (about {{amount}}) I'd have missed claiming. 🚗💸 MileSprout logs every mile automatically.": "ਮੇਰੀ ਡਿਲੀਵਰੀ ਐਪ ਨੇ ਪਿਛਲੇ ਮਹੀਨੇ {{counted}} ਕਿ.ਮੀ. ਗਿਣੇ। MileSprout ਨੇ ਕੰਮ ਦੇ {{logged}} ਕਿ.ਮੀ. ਦਰਜ ਕੀਤੇ: ਯਾਨੀ {{extra}} ਕਿ.ਮੀ. (ਲਗਭਗ {{amount}}) ਜੋ ਕਲੇਮ ਕਰਨੋਂ ਰਹਿ ਜਾਂਦੇ। 🚗💸 MileSprout ਹਰ ਕਿਲੋਮੀਟਰ ਆਪਣੇ-ਆਪ ਦਰਜ ਕਰਦਾ ਹੈ।",
