  "My delivery app counted {{counted}} km this week. MileSprout logged {{logged}} work km: that's {{extra}} km (about {{amount}}) I'd have missed claiming. 🚗💸 MileSprout logs every mile automatically.": "ਮੇਰੀ ਡਿਲੀਵਰੀ ਐਪ ਨੇ ਇਸ ਹਫ਼ਤੇ {{counted}} ਕਿ.ਮੀ. ਗਿਣੇ। MileSprout ਨੇ ਕੰਮ ਦੇ {{logged}} ਕਿ.ਮੀ. ਦਰਜ ਕੀਤੇ: ਯਾਨੀ {{extra}} ਕਿ.ਮੀ. (ਲਗਭਗ {{amount}}) ਜੋ ਕਲੇਮ ਕਰਨੋਂ ਰਹਿ ਜਾਂਦੇ। 🚗💸 MileSprout ਹਰ ਕਿਲੋਮੀਟਰ ਆਪਣੇ-ਆਪ ਦਰਜ ਕਰਦਾ ਹੈ।",
  "My delivery app counted {{counted}} miles last month. MileSprout logged {{logged}} work miles: that's {{extra}} miles (about {{amount}}) I'd have missed claiming. 🚗💸 MileSprout logs every mile automatically.": "ਮੇਰੀ ਡਿਲੀਵਰੀ ਐਪ ਨੇ ਪਿਛਲੇ ਮਹੀਨੇ {{counted}} ਮੀਲ ਗਿਣੇ। MileSprout ਨੇ ਕੰਮ ਦੇ {{logged}} ਮੀਲ ਦਰਜ ਕੀਤੇ: ਯਾਨੀ {{extra}} ਮੀਲ (ਲਗਭਗ {{amount}}) ਜੋ ਕਲੇਮ ਕਰਨੋਂ ਰਹਿ ਜਾਂਦੇ। 🚗💸 MileSprout ਹਰ ਮੀਲ ਆਪਣੇ-ਆਪ ਦਰਜ ਕਰਦਾ ਹੈ।",
  "My delivery app counted {{counted}} miles this month. MileSprout logged {{logged}} work miles: that's {{extra}} miles (about {{amount}}) I'd have missed claiming. 🚗💸 MileSprout logs every mile automatically.": "ਮੇਰੀ ਡਿਲੀਵਰੀ ਐਪ ਨੇ ਇਸ ਮਹੀਨੇ {{counted}} ਮੀਲ ਗਿਣੇ। MileSprout ਨੇ ਕੰਮ ਦੇ {{logged}} ਮੀਲ ਦਰਜ ਕੀਤੇ: ਯਾਨੀ {{extra}} ਮੀਲ (ਲਗਭਗ {{amount}}) ਜੋ ਕਲੇਮ ਕਰਨੋਂ ਰਹਿ ਜਾਂਦੇ। 🚗💸 MileSprout ਹਰ ਮੀਲ ਆਪਣੇ-ਆਪ ਦਰਜ ਕਰਦਾ ਹੈ।",
  "My delivery app counted {{counted}} miles this week. MileSprout logged {{logged}} work miles: that's {{extra}} miles (about {{amount}}) I'd have missed claiming. 🚗💸 MileSprout logs every mile automatically.": "ਮੇਰੀ ਡਿਲੀਵਰੀ ਐਪ ਨੇ ਇਸ ਹਫ਼ਤੇ {{counted}} ਮੀਲ ਗਿਣੇ। MileSprout ਨੇ ਕੰਮ ਦੇ {{logged}} ਮੀਲ ਦਰਜ ਕੀਤੇ: ਯਾਨੀ {{extra}} ਮੀਲ (ਲਗਭਗ {{amount}}) ਜੋ ਕਲੇਮ ਕਰਨੋਂ ਰਹਿ ਜਾਂਦੇ। 🚗💸 MileSprout ਹਰ ਮੀਲ ਆਪਣੇ-ਆਪ ਦਰਜ ਕਰਦਾ ਹੈ।",
