  "Once a year: by April 30, or June 15 if you’re self-employed (any tax owing is still due April 30). Self-employed claim vehicle costs on form T2125.": "ਸਾਲ ਵਿੱਚ ਇੱਕ ਵਾਰ: 30 ਅਪ੍ਰੈਲ ਤੱਕ, ਜਾਂ ਸਵੈ-ਰੁਜ਼ਗਾਰ ਵਾਲਿਆਂ ਲਈ 15 ਜੂਨ ਤੱਕ (ਬਣਦਾ ਟੈਕਸ ਫਿਰ ਵੀ 30 ਅਪ੍ਰੈਲ ਤੱਕ ਭਰਨਾ ਹੁੰਦਾ ਹੈ)। ਸਵੈ-ਰੁਜ਼ਗਾਰ ਵਾਲੇ ਗੱਡੀ ਦੇ ਖ਼ਰਚੇ form T2125 ’ਤੇ ਕਲੇਮ ਕਰਦੇ ਹਨ।",
  "Once a year: lodge by 31 October after the income year ends (30 June), or later if you use a registered tax agent and sign up with them before 31 October.": "ਸਾਲ ਵਿੱਚ ਇੱਕ ਵਾਰ: ਆਮਦਨ ਸਾਲ ਖ਼ਤਮ ਹੋਣ (30 ਜੂਨ) ਤੋਂ ਬਾਅਦ 31 ਅਕਤੂਬਰ ਤੱਕ ਭਰੋ, ਜਾਂ ਬਾਅਦ ਵਿੱਚ, ਜੇ 31 ਅਕਤੂਬਰ ਤੋਂ ਪਹਿਲਾਂ ਕਿਸੇ ਰਜਿਸਟਰਡ ਟੈਕਸ ਏਜੰਟ ਨਾਲ ਸਾਈਨ ਅੱਪ ਹੋ ਜਾਵੇ।",
  "One quick switch in Settings": "ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਬੱਸ ਇੱਕ ਛੋਟੀ ਜਿਹੀ ਤਬਦੀਲੀ",
  "One week left in the {{year}} tax year 🏁": "{{year}} ਟੈਕਸ ਸਾਲ ਦਾ ਇੱਕ ਹਫ਼ਤਾ ਬਾਕੀ 🏁",
