  "Save start as a place": "ਸ਼ੁਰੂਆਤੀ ਪਤਾ ਥਾਂ ਵਜੋਂ ਸੇਵ ਕਰੋ",
  "Save start as a place: {{name}}": "ਸ਼ੁਰੂਆਤੀ ਪਤਾ ਥਾਂ ਵਜੋਂ ਸੇਵ ਕਰੋ: {{name}}",
