  "Save work hours": "ਕੰਮ ਦੇ ਘੰਟੇ ਸੇਵ ਕਰੋ",
  "Saved. New drives will use these hours.": "ਸੇਵ ਹੋ ਗਿਆ। ਨਵੇਂ ਟ੍ਰਿਪ ਇਹ ਘੰਟੇ ਵਰਤਣਗੇ।",
  "Saved. The PDF report includes these readings.": "ਸੇਵ ਹੋ ਗਿਆ। PDF ਰਿਪੋਰਟ ਵਿੱਚ ਇਹ ਰੀਡਿੰਗ ਸ਼ਾਮਲ ਹਨ।",
