  "Search an address or place": "ਪਤਾ ਜਾਂ ਥਾਂ ਖੋਜੋ",
  "Search for its address, or use “I’m here now”.": "ਇਸਦਾ ਪਤਾ ਖੋਜੋ, ਜਾਂ “ਮੈਂ ਹੁਣ ਇੱਥੇ ਹਾਂ” ਵਰਤੋ।",
  "Select": "ਚੁਣੋ",
  "Select {{count}} unsorted": {
    "one": "{{count}} ਬਿਨਾਂ ਛਾਂਟਿਆ ਚੁਣੋ",
    "other": "{{count}} ਬਿਨਾਂ ਛਾਂਟੇ ਚੁਣੋ"
  },
  "Select several trips to sort at once": "ਇੱਕੋ ਵਾਰ ਛਾਂਟਣ ਲਈ ਕਈ ਟ੍ਰਿਪ ਚੁਣੋ",
  "Self Assessment return": "Self Assessment ਰਿਟਰਨ",
  "Self Assessment return due in a week 📄": "Self Assessment ਰਿਟਰਨ ਇੱਕ ਹਫ਼ਤੇ ਵਿੱਚ ਭਰਨੀ ਹੈ 📄",
  "Self-employed (T2125): claim your actual vehicle costs multiplied by your business-use share, which is business kilometres divided by total kilometres driven in the year. Record your odometer readings below to work it out.": "ਸਵੈ-ਰੁਜ਼ਗਾਰ ਵਾਲੇ (T2125): ਆਪਣੀ ਗੱਡੀ ਦੇ ਅਸਲ ਖ਼ਰਚਿਆਂ ਨੂੰ ਬਿਜ਼ਨਸ-ਵਰਤੋਂ ਵਾਲੇ ਹਿੱਸੇ ਨਾਲ ਗੁਣਾ ਕਰਕੇ ਕਲੇਮ ਕਰੋ। ਇਹ ਹਿੱਸਾ ਹੈ ਬਿਜ਼ਨਸ ਕਿਲੋਮੀਟਰ ਭਾਗ ਸਾਲ ਵਿੱਚ ਚਲਾਏ ਕੁੱਲ ਕਿਲੋਮੀਟਰ। ਇਸਦਾ ਹਿਸਾਬ ਲਾਉਣ ਲਈ ਹੇਠਾਂ ਆਪਣੀ ਓਡੋਮੀਟਰ ਰੀਡਿੰਗ ਦਰਜ ਕਰੋ।",
  "Self-employed: enter business, commuting and other miles on Schedule C, Part IV (lines 44a–44c) and the deduction on line 9, Car and truck expenses, using the standard mileage rate.": "ਸਵੈ-ਰੁਜ਼ਗਾਰ ਵਾਲੇ: ਬਿਜ਼ਨਸ, ਘਰ-ਕੰਮ ਆਉਣ-ਜਾਣ ਅਤੇ ਹੋਰ ਮੀਲ Schedule C, Part IV (ਲਾਈਨਾਂ 44a–44c) ’ਤੇ ਭਰੋ, ਅਤੇ ਸਟੈਂਡਰਡ ਮਾਈਲੇਜ ਰੇਟ ਵਰਤ ਕੇ ਕਟੌਤੀ ਲਾਈਨ 9, Car and truck expenses ’ਤੇ ਭਰੋ।",
  "Self-employed: once a year on Form 1040 with Schedule C, due April 15 (October 15 with an extension, but tax owed is still due in April).": "ਸਵੈ-ਰੁਜ਼ਗਾਰ ਵਾਲੇ: ਸਾਲ ਵਿੱਚ ਇੱਕ ਵਾਰ Form 1040 ਅਤੇ Schedule C ’ਤੇ, ਆਖ਼ਰੀ ਤਾਰੀਖ਼ 15 ਅਪ੍ਰੈਲ (ਐਕਸਟੈਂਸ਼ਨ ਨਾਲ 15 ਅਕਤੂਬਰ, ਪਰ ਬਣਦਾ ਟੈਕਸ ਫਿਰ ਵੀ ਅਪ੍ਰੈਲ ਵਿੱਚ ਭਰਨਾ ਹੁੰਦਾ ਹੈ)।",
  "Self-employed: once a year, online by 31 January after the tax year ends (5 April). Your mileage goes in Car, van and travel expenses.": "ਸਵੈ-ਰੁਜ਼ਗਾਰ ਵਾਲੇ: ਸਾਲ ਵਿੱਚ ਇੱਕ ਵਾਰ, ਟੈਕਸ ਸਾਲ ਖ਼ਤਮ ਹੋਣ (5 ਅਪ੍ਰੈਲ) ਤੋਂ ਬਾਅਦ 31 ਜਨਵਰੀ ਤੱਕ ਔਨਲਾਈਨ। ਤੁਹਾਡੀ ਮਾਈਲੇਜ Car, van and travel expenses ਵਿੱਚ ਜਾਂਦੀ ਹੈ।",
  "Self-employed: this total is your simplified expenses figure for business mileage. Include it in Car, van and travel expenses on your Self Assessment return.": "ਸਵੈ-ਰੁਜ਼ਗਾਰ ਵਾਲੇ: ਇਹ ਕੁੱਲ ਰਕਮ ਬਿਜ਼ਨਸ ਮਾਈਲੇਜ ਲਈ ਤੁਹਾਡਾ simplified expenses ਅੰਕੜਾ ਹੈ। ਇਸਨੂੰ ਆਪਣੀ Self Assessment ਰਿਟਰਨ ਵਿੱਚ Car, van and travel expenses ਵਿੱਚ ਪਾਓ।",
  "Set hours": "ਪੱਕੇ ਘੰਟੇ",
  "Let MileSprout sort for you ⏱️": "MileSprout ਨੂੰ ਛਾਂਟਣ ਦਿਓ ⏱️",
  "Set location to “Always” and MileSprout logs every drive, even when it’s closed.": "ਟਿਕਾਣਾ “ਹਮੇਸ਼ਾਂ” ’ਤੇ ਕਰੋ ਅਤੇ MileSprout ਹਰ ਟ੍ਰਿਪ ਦਰਜ ਕਰੇਗਾ, ਐਪ ਬੰਦ ਹੋਣ ’ਤੇ ਵੀ।",
  "Set up auto-logging": "ਆਟੋਮੈਟਿਕ ਟ੍ਰੈਕਿੰਗ ਸੈੱਟ ਕਰੋ",
  "Sets your currency, miles or kilometres, tax year and official mileage rate. You can change it later.": "ਇਸ ਨਾਲ ਐਪ ਦੀ ਕਰੰਸੀ, ਮੀਲ ਜਾਂ ਕਿਲੋਮੀਟਰ, ਟੈਕਸ ਸਾਲ ਅਤੇ ਸਰਕਾਰੀ ਮਾਈਲੇਜ ਰੇਟ ਤੈਅ ਹੁੰਦੇ ਹਨ। ਇਸਨੂੰ ਬਾਅਦ ਵਿੱਚ ਬਦਲਿਆ ਜਾ ਸਕਦਾ ਹੈ।",
