  "Tax return due in a week 📄": "ਟੈਕਸ ਰਿਟਰਨ ਇੱਕ ਹਫ਼ਤੇ ਵਿੱਚ ਭਰਨੀ ਹੈ 📄",
  "Tell MileSprout your work hours once and it sorts most drives for you. Takes 30 seconds.": "MileSprout ਨੂੰ ਇੱਕ ਵਾਰ ਆਪਣੇ ਕੰਮ ਦੇ ਘੰਟੇ ਦੱਸੋ, ਤੇ ਇਹ ਤੁਹਾਡੇ ਲਈ ਜ਼ਿਆਦਾਤਰ ਟ੍ਰਿਪ ਛਾਂਟ ਦੇਵੇਗਾ। ਬੱਸ 30 ਸਕਿੰਟ ਲੱਗਦੇ ਹਨ।",
  "Terms of Use": "ਵਰਤੋਂ ਦੀਆਂ ਸ਼ਰਤਾਂ",
  "The {{year}} tax year ends soon": "{{year}} ਟੈਕਸ ਸਾਲ ਜਲਦੀ ਖ਼ਤਮ ਹੋ ਰਿਹਾ ਹੈ",
  "The App Store couldn’t start the purchase. Please try again.": "App Store ਖ਼ਰੀਦ ਸ਼ੁਰੂ ਨਹੀਂ ਕਰ ਸਕਿਆ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "The ATO cents per km method is for cars only. Motorbike and bicycle trips are logged for your records; claim their actual costs instead.": "ATO ਦਾ cents per km method ਸਿਰਫ਼ ਕਾਰਾਂ ਲਈ ਹੈ। ਮੋਟਰਸਾਈਕਲ ਅਤੇ ਸਾਈਕਲ ਦੇ ਟ੍ਰਿਪ ਤੁਹਾਡੇ ਰਿਕਾਰਡ ਲਈ ਦਰਜ ਹੁੰਦੇ ਹਨ; ਉਨ੍ਹਾਂ ਲਈ ਅਸਲ ਖ਼ਰਚੇ ਕਲੇਮ ਕਰੋ।",
  "The CRA per-km rate is for cars. Motorbike and bicycle trips are logged for your records; claim their actual costs instead.": "CRA ਦਾ ਪ੍ਰਤੀ ਕਿ.ਮੀ. ਰੇਟ ਕਾਰਾਂ ਲਈ ਹੈ। ਮੋਟਰਸਾਈਕਲ ਅਤੇ ਸਾਈਕਲ ਦੇ ਟ੍ਰਿਪ ਤੁਹਾਡੇ ਰਿਕਾਰਡ ਲਈ ਦਰਜ ਹੁੰਦੇ ਹਨ; ਉਨ੍ਹਾਂ ਲਈ ਅਸਲ ਖ਼ਰਚੇ ਕਲੇਮ ਕਰੋ।",
  "The end reading must be higher than the start reading.": "ਅੰਤ ਵਾਲੀ ਰੀਡਿੰਗ ਸ਼ੁਰੂ ਵਾਲੀ ਰੀਡਿੰਗ ਤੋਂ ਵੱਧ ਹੋਣੀ ਚਾਹੀਦੀ ਹੈ।",
  "The IRS asks for a record made at or near the time of each trip, showing the date, where you went, the business purpose and the miles.": "IRS ਹਰ ਟ੍ਰਿਪ ਵੇਲੇ ਜਾਂ ਉਸਦੇ ਨੇੜੇ-ਤੇੜੇ ਬਣਿਆ ਰਿਕਾਰਡ ਮੰਗਦਾ ਹੈ, ਜਿਸ ਵਿੱਚ ਤਾਰੀਖ਼, ਮੰਜ਼ਿਲ, ਬਿਜ਼ਨਸ ਮਕਸਦ ਅਤੇ ਮੀਲ ਹੋਣ।",
  "The IRS standard mileage rate is for cars, vans and pickups. Motorbike and bicycle trips are logged for your records; claim their actual costs instead.": "IRS ਸਟੈਂਡਰਡ ਮਾਈਲੇਜ ਰੇਟ ਕਾਰਾਂ, ਵੈਨਾਂ ਅਤੇ ਪਿਕਅੱਪਾਂ ਲਈ ਹੈ। ਮੋਟਰਸਾਈਕਲ ਅਤੇ ਸਾਈਕਲ ਦੇ ਟ੍ਰਿਪ ਤੁਹਾਡੇ ਰਿਕਾਰਡ ਲਈ ਦਰਜ ਹੁੰਦੇ ਹਨ; ਉਨ੍ਹਾਂ ਲਈ ਅਸਲ ਖ਼ਰਚੇ ਕਲੇਮ ਕਰੋ।",
  "The purchase didn’t go through. Please try again.": "ਖ਼ਰੀਦ ਪੂਰੀ ਨਹੀਂ ਹੋਈ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "The weekend’s nearly over 🛋️": "ਵੀਕਐਂਡ ਮੁੱਕਣ ਵਾਲਾ ਹੈ 🛋️",
  "Sort them before Monday. It takes a minute.": "ਸੋਮਵਾਰ ਤੋਂ ਪਹਿਲਾਂ ਇਨ੍ਹਾਂ ਨੂੰ ਛਾਂਟ ਲਓ। ਬੱਸ ਇੱਕ ਮਿੰਟ ਲੱਗਦਾ ਹੈ।",
