  "This is CRA’s reimbursement rate for employees. If you’re self-employed, CRA usually wants your actual car costs, so treat the figure as an estimate.": "ਇਹ ਮੁਲਾਜ਼ਮਾਂ ਲਈ CRA ਦਾ ਪੈਸੇ ਵਾਪਸ ਕਰਨ ਵਾਲਾ ਰੇਟ ਹੈ। ਸਵੈ-ਰੁਜ਼ਗਾਰ ਵਾਲਿਆਂ ਤੋਂ CRA ਆਮ ਤੌਰ ’ਤੇ ਕਾਰ ਦੇ ਅਸਲ ਖ਼ਰਚੇ ਮੰਗਦਾ ਹੈ, ਇਸ ਲਈ ਇਸ ਅੰਕੜੇ ਨੂੰ ਅੰਦਾਜ਼ਾ ਹੀ ਸਮਝੋ।",
