  "Trades, sales, care, office. Drives in your hours count as work.": "ਟਰੇਡ, ਸੇਲਜ਼, ਕੇਅਰ, ਦਫ਼ਤਰ। ਤੁਹਾਡੇ ਕੰਮ ਦੇ ਘੰਟਿਆਂ ਵਿੱਚ ਹੋਏ ਟ੍ਰਿਪ ਕੰਮ ਦੇ ਗਿਣੇ ਜਾਂਦੇ ਹਨ।",
