  "United States": "ਅਮਰੀਕਾ",
  "Unless a rule says otherwise (work hours, a commute, a route you’ve taught it). Swipe left on any that were personal; only work drives should be claimed.": "ਜਦੋਂ ਤੱਕ ਕੋਈ ਨਿਯਮ ਹੋਰ ਨਾ ਕਹੇ (ਕੰਮ ਦੇ ਘੰਟੇ, ਘਰ-ਕੰਮ ਆਉਣ-ਜਾਣ, ਜਾਂ ਤੁਹਾਡਾ ਸਿਖਾਇਆ ਰਸਤਾ)। ਜੋ ਨਿੱਜੀ ਸਨ ਉਨ੍ਹਾਂ ਨੂੰ ਖੱਬੇ ਸਵਾਈਪ ਕਰੋ; ਸਿਰਫ਼ ਕੰਮ ਦੇ ਟ੍ਰਿਪ ਹੀ ਕਲੇਮ ਕਰਨੇ ਚਾਹੀਦੇ ਹਨ।",
