  "When and how to claim with {{authority}}": "{{authority}} ਕੋਲ ਕਦੋਂ ਅਤੇ ਕਿਵੇਂ ਕਲੇਮ ਕਰਨਾ ਹੈ",
  "Where do you drive?": "ਤੁਹਾਡੀ ਡਰਾਈਵਿੰਗ ਕਿਸ ਦੇਸ਼ ਵਿੱਚ ਹੁੰਦੀ ਹੈ?",
