  "Work-related car use (cents per km method)": "ਕੰਮ ਨਾਲ ਜੁੜੀ ਕਾਰ ਦੀ ਵਰਤੋਂ (cents per km method)",
  "worth about {{amount}}": "ਲਗਭਗ {{amount}} ਦੀ ਕੀਮਤ",
  "Stay warm and drive safely ❄️": "ਗਰਮ ਕੱਪੜੇ ਪਾਓ ਅਤੇ ਧਿਆਨ ਨਾਲ ਚਲਾਓ ❄️",
