  "This backup is locked with a key from your iCloud Keychain that hasn’t reached this iPhone yet. Check that iCloud Keychain is on (iPhone Settings → your name → iCloud), wait a minute, then try again.": "ਇਹ ਬੈਕਅੱਪ ਤੁਹਾਡੇ iCloud Keychain ਦੀ ਇੱਕ ਕੁੰਜੀ ਨਾਲ ਲੌਕ ਹੈ, ਜੋ ਹਾਲੇ ਇਸ iPhone ਤੱਕ ਨਹੀਂ ਪਹੁੰਚੀ। ਚੈੱਕ ਕਰੋ ਕਿ iCloud Keychain ਚਾਲੂ ਹੈ (iPhone ਦੀਆਂ ਸੈਟਿੰਗਾਂ → ਤੁਹਾਡਾ ਨਾਂ → iCloud), ਇੱਕ ਮਿੰਟ ਰੁਕੋ, ਫਿਰ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "This backup was made by a newer version of MileSprout. Update the app, then try again.": "ਇਹ ਬੈਕਅੱਪ MileSprout ਦੇ ਨਵੇਂ ਵਰਜ਼ਨ ਨਾਲ ਬਣਿਆ ਸੀ। ਐਪ ਅੱਪਡੇਟ ਕਰੋ, ਫਿਰ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "The backup hasn’t downloaded from iCloud yet. Check your connection and try again.": "ਬੈਕਅੱਪ ਹਾਲੇ iCloud ਤੋਂ ਡਾਊਨਲੋਡ ਨਹੀਂ ਹੋਇਆ। ਆਪਣਾ ਕਨੈਕਸ਼ਨ ਚੈੱਕ ਕਰੋ ਅਤੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
