  "{{vehicle}} has done {{distance}} of work driving this year. Cents per km stops counting at 5,000 km.": "ਇਸ ਸਾਲ {{vehicle}} ਨਾਲ {{distance}} ਦੀ ਕੰਮ ਦੀ ਡਰਾਈਵਿੰਗ ਹੋ ਚੁੱਕੀ ਹੈ। cents per km ਵਿੱਚ 5,000 ਕਿ.ਮੀ. ਤੋਂ ਬਾਅਦ ਗਿਣਤੀ ਨਹੀਂ ਹੁੰਦੀ।",
  "{{vehicle}} is on track for about {{distance}} of work driving this year. Cents per km stops counting at 5,000 km.": "ਇਸ ਸਾਲ {{vehicle}} ਨਾਲ ਲਗਭਗ {{distance}} ਦੀ ਕੰਮ ਦੀ ਡਰਾਈਵਿੰਗ ਹੋਣ ਦਾ ਅੰਦਾਜ਼ਾ ਹੈ। cents per km ਵਿੱਚ 5,000 ਕਿ.ਮੀ. ਤੋਂ ਬਾਅਦ ਗਿਣਤੀ ਨਹੀਂ ਹੁੰਦੀ।",
  "Client visit": "ਕਲਾਇੰਟ ਵਿਜ਼ਿਟ",
