  "I’ve logged {{amount}} of work mileage with MileSprout 🚗 Every mile counted, automatically.": "ਮੈਂ MileSprout ਨਾਲ {{amount}} ਦੀ ਕੰਮ ਦੀ ਮਾਈਲੇਜ ਦਰਜ ਕੀਤੀ ਹੈ 🚗 ਹਰ ਟ੍ਰਿਪ ਗਿਣਿਆ ਗਿਆ, ਆਪਣੇ-ਆਪ।",
