  "A friend’s code can only be entered in the first 30 days after installing MileSprout.": "ਦੋਸਤ ਦਾ ਕੋਡ MileSprout ਇੰਸਟਾਲ ਕਰਨ ਤੋਂ ਬਾਅਦ ਪਹਿਲੇ 30 ਦਿਨਾਂ ਵਿੱਚ ਹੀ ਭਰਿਆ ਜਾ ਸਕਦਾ ਹੈ।",
