  "You’ve been parked at home for a while and your shift is still on. Drives after it ends aren’t counted as work.": "ਤੁਸੀਂ ਕਾਫ਼ੀ ਦੇਰ ਤੋਂ ਘਰ ਪਾਰਕ ਹੋ ਅਤੇ ਤੁਹਾਡੀ ਸ਼ਿਫਟ ਅਜੇ ਵੀ ਚੱਲ ਰਹੀ ਹੈ। ਸ਼ਿਫਟ ਖ਼ਤਮ ਹੋਣ ਤੋਂ ਬਾਅਦ ਦੇ ਟ੍ਰਿਪ ਕੰਮ ਵਿੱਚ ਨਹੀਂ ਗਿਣੇ ਜਾਂਦੇ।",
  "You’ve been parked at home since {{time}}. Drives after the shift aren’t counted as work.": "ਤੁਸੀਂ {{time}} ਵਜੇ ਤੋਂ ਘਰ ਪਾਰਕ ਹੋ। ਸ਼ਿਫਟ ਤੋਂ ਬਾਅਦ ਦੇ ਟ੍ਰਿਪ ਕੰਮ ਵਿੱਚ ਨਹੀਂ ਗਿਣੇ ਜਾਂਦੇ।",
  "Your shift ended after 16 hours": "ਤੁਹਾਡੀ ਸ਼ਿਫਟ 16 ਘੰਟਿਆਂ ਬਾਅਦ ਖ਼ਤਮ ਹੋ ਗਈ",
  "Precise Location is off": "ਸਹੀ ਟਿਕਾਣਾ ਬੰਦ ਹੈ",
  "MileSprout only gets a rough position, so drives can’t be measured. In Settings, tap Location and turn on Precise Location.": "MileSprout ਨੂੰ ਸਿਰਫ਼ ਅੰਦਾਜ਼ਨ ਟਿਕਾਣਾ ਮਿਲ ਰਿਹਾ ਹੈ, ਇਸ ਲਈ ਟ੍ਰਿਪ ਮਾਪੇ ਨਹੀਂ ਜਾ ਸਕਦੇ। ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਟਿਕਾਣਾ ’ਤੇ ਟੈਪ ਕਰੋ ਅਤੇ ਸਹੀ ਟਿਕਾਣਾ ਚਾਲੂ ਕਰੋ।",
  "Tracking has stopped": "ਟ੍ਰੈਕਿੰਗ ਰੁਕ ਗਈ ਹੈ",
