  "Tracking may have stopped": "ਹੋ ਸਕਦਾ ਹੈ ਟ੍ਰੈਕਿੰਗ ਰੁਕ ਗਈ ਹੋਵੇ",
  "No location since {{time}}, in the middle of a drive.": "ਟ੍ਰਿਪ ਦੇ ਵਿਚਕਾਰ {{time}} ਤੋਂ ਕੋਈ ਟਿਕਾਣਾ ਨਹੀਂ ਮਿਲਿਆ।",
  "Turn tracking back on": "ਟ੍ਰੈਕਿੰਗ ਮੁੜ ਚਾਲੂ ਕਰੋ",
