  "A drive may have been missed": "ਹੋ ਸਕਦਾ ਹੈ ਇੱਕ ਟ੍ਰਿਪ ਰਹਿ ਗਿਆ ਹੋਵੇ",
  "About {{distance}} may be missing. Add the missed trip?": "ਲਗਭਗ {{distance}} ਰਹਿ ਗਏ ਹੋ ਸਕਦੇ ਹਨ। ਰਹਿ ਗਿਆ ਟ੍ਰਿਪ ਜੋੜਨਾ ਹੈ?",
  "Your phone moved about {{distance}} between {{from}} and {{to}}, but no drive was logged. Add the missed trip?": "ਤੁਹਾਡਾ ਫ਼ੋਨ {{from}} ਤੋਂ {{to}} ਵਿਚਕਾਰ ਲਗਭਗ {{distance}} ਅੱਗੇ ਗਿਆ, ਪਰ ਕੋਈ ਟ੍ਰਿਪ ਦਰਜ ਨਹੀਂ ਹੋਇਆ। ਰਹਿ ਗਿਆ ਟ੍ਰਿਪ ਜੋੜਨਾ ਹੈ?",
