  "Location access for MileSprout is off, so drives aren’t being logged. Tap to turn it back on.": "MileSprout ਲਈ ਟਿਕਾਣੇ ਦੀ ਇਜਾਜ਼ਤ ਬੰਦ ਹੈ, ਇਸ ਲਈ ਟ੍ਰਿਪ ਦਰਜ ਨਹੀਂ ਹੋ ਰਹੇ। ਮੁੜ ਚਾਲੂ ਕਰਨ ਲਈ ਟੈਪ ਕਰੋ।",
