  "{{authority}} expects a purpose for every work drive. One tap each.": "{{authority}} ਕੰਮ ਦੇ ਹਰ ਟ੍ਰਿਪ ਦਾ ਮਕਸਦ ਮੰਗਦਾ ਹੈ। ਹਰ ਇੱਕ ਲਈ ਬੱਸ ਇੱਕ ਟੈਪ।",
