  "{{authority}} expects a purpose for every work drive. Add them before you export?": "{{authority}} ਕੰਮ ਦੇ ਹਰ ਟ੍ਰਿਪ ਦਾ ਮਕਸਦ ਮੰਗਦਾ ਹੈ। ਐਕਸਪੋਰਟ ਤੋਂ ਪਹਿਲਾਂ ਜੋੜਨੇ ਹਨ?",
  "Export anyway": "ਫਿਰ ਵੀ ਐਕਸਪੋਰਟ ਕਰੋ",
  "Add purposes": "ਮਕਸਦ ਜੋੜੋ",
  "Usual purpose": "ਆਮ ਮਕਸਦ",
  "Clear": "ਹਟਾਓ",
  "Filled in for work drives that have none, so your tax records are complete. Shift drives use “Deliveries” unless you choose one.": "ਕੰਮ ਦੇ ਜਿਨ੍ਹਾਂ ਟ੍ਰਿਪਾਂ ਦਾ ਮਕਸਦ ਨਹੀਂ, ਉਨ੍ਹਾਂ ਵਿੱਚ ਇਹ ਭਰਿਆ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਜੋ ਤੁਹਾਡੇ ਟੈਕਸ ਰਿਕਾਰਡ ਪੂਰੇ ਰਹਿਣ। ਸ਼ਿਫਟ ਦੇ ਟ੍ਰਿਪ “ਡਿਲੀਵਰੀਆਂ” ਵਰਤਦੇ ਹਨ, ਜਦ ਤੱਕ ਤੁਸੀਂ ਕੋਈ ਹੋਰ ਨਾ ਚੁਣੋ।",
  "Filled in for work drives that have none, so your tax records are complete. You can change it on any trip.": "ਕੰਮ ਦੇ ਜਿਨ੍ਹਾਂ ਟ੍ਰਿਪਾਂ ਦਾ ਮਕਸਦ ਨਹੀਂ, ਉਨ੍ਹਾਂ ਵਿੱਚ ਇਹ ਭਰਿਆ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਜੋ ਤੁਹਾਡੇ ਟੈਕਸ ਰਿਕਾਰਡ ਪੂਰੇ ਰਹਿਣ। ਤੁਸੀਂ ਇਸਨੂੰ ਕਿਸੇ ਵੀ ਟ੍ਰਿਪ ਵਿੱਚ ਬਦਲ ਸਕਦੇ ਹੋ।",
  "None: ask me each time": "ਕੋਈ ਨਹੀਂ: ਹਰ ਵਾਰ ਪੁੱਛੋ",
  "What are most of your work drives for?": "ਤੁਹਾਡੇ ਜ਼ਿਆਦਾਤਰ ਕੰਮ ਦੇ ਟ੍ਰਿਪ ਕਿਸ ਲਈ ਹੁੰਦੇ ਹਨ?",
  "Tax offices want a purpose for every work drive. We’ll fill this in for you, and you can change it on any trip.": "ਟੈਕਸ ਵਿਭਾਗ ਕੰਮ ਦੇ ਹਰ ਟ੍ਰਿਪ ਦਾ ਮਕਸਦ ਮੰਗਦਾ ਹੈ। ਅਸੀਂ ਇਹ ਤੁਹਾਡੇ ਲਈ ਭਰ ਦੇਵਾਂਗੇ, ਅਤੇ ਤੁਸੀਂ ਇਸਨੂੰ ਕਿਸੇ ਵੀ ਟ੍ਰਿਪ ਵਿੱਚ ਬਦਲ ਸਕਦੇ ਹੋ।",
  "Pick all that apply. The first one you pick is filled in for you.": "ਜੋ ਵੀ ਲਾਗੂ ਹੋਣ, ਸਭ ਚੁਣੋ। ਜੋ ਪਹਿਲਾਂ ਚੁਣੋਗੇ, ਉਹ ਅਸੀਂ ਤੁਹਾਡੇ ਲਈ ਭਰ ਦੇਵਾਂਗੇ।",
  "Filled in for you": "ਤੁਹਾਡੇ ਲਈ ਭਰਿਆ ਜਾਵੇਗਾ",
  "Default": "ਆਮ",
  "Allow While Using App": "ਐਪ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਸਮੇਂ ਇਜਾਜ਼ਤ ਦਿਓ",
  "Change to Always Allow": "ਹਮੇਸ਼ਾਂ ਇਜਾਜ਼ਤ ਦੇਣ ’ਤੇ ਬਦਲੋ",
  "Tap “{{button}}”": "“{{button}}” ’ਤੇ ਟੈਪ ਕਰੋ",
  "{{step}} OF 2": "2 ਵਿੱਚੋਂ {{step}}",
  "No account. Your trips stay on your phone.": "ਕੋਈ ਖਾਤਾ ਨਹੀਂ। ਤੁਹਾਡੇ ਟ੍ਰਿਪ ਤੁਹਾਡੇ ਫ਼ੋਨ ’ਤੇ ਹੀ ਰਹਿੰਦੇ ਹਨ।",
  "Is this home? {{place}}": "ਕੀ ਇਹ ਘਰ ਹੈ? {{place}}",
  "You stopped here for the night. Trips to and from it will read “Home”.": "ਤੁਸੀਂ ਰਾਤ ਇੱਥੇ ਹੀ ਕੱਟੀ। ਇੱਥੋਂ ਆਉਣ-ਜਾਣ ਵਾਲੇ ਟ੍ਰਿਪਾਂ ’ਤੇ “ਘਰ” ਲਿਖਿਆ ਆਵੇਗਾ।",
  "Yes, that’s home": "ਹਾਂ, ਇਹ ਘਰ ਹੈ",
  "No": "ਨਹੀਂ",
  "Is this work? {{place}}": "ਕੀ ਇਹ ਕੰਮ ਦੀ ਥਾਂ ਹੈ? {{place}}",
  "You’re often parked here in your work hours. Trips will read “Work”, and drives between home and work are flagged as commutes.": "ਕੰਮ ਦੇ ਘੰਟਿਆਂ ਵਿੱਚ ਤੁਹਾਡੀ ਗੱਡੀ ਅਕਸਰ ਇੱਥੇ ਖੜ੍ਹੀ ਹੁੰਦੀ ਹੈ। ਟ੍ਰਿਪਾਂ ’ਤੇ “ਕੰਮ” ਲਿਖਿਆ ਆਵੇਗਾ, ਅਤੇ ਘਰ-ਕੰਮ ਆਉਣ-ਜਾਣ ਵੱਖਰਾ ਪਛਾਣਿਆ ਜਾਵੇਗਾ।",
  "Yes, that’s work": "ਹਾਂ, ਇਹ ਕੰਮ ਦੀ ਥਾਂ ਹੈ",
  "One more for accuracy: Motion & Fitness": "ਸ਼ੁੱਧਤਾ ਲਈ ਇੱਕ ਹੋਰ: ਮੋਸ਼ਨ ਅਤੇ ਫਿਟਨੈੱਸ",
  "Lets MileSprout tell driving from walking, so a stroll is never logged as a trip. It stays on your phone.": "ਇਸ ਨਾਲ MileSprout ਗੱਡੀ ਚਲਾਉਣ ਅਤੇ ਪੈਦਲ ਚੱਲਣ ਵਿੱਚ ਫ਼ਰਕ ਕਰ ਸਕਦਾ ਹੈ, ਤਾਂ ਜੋ ਸੈਰ ਕਦੇ ਵੀ ਟ੍ਰਿਪ ਵਜੋਂ ਦਰਜ ਨਾ ਹੋਵੇ। ਇਹ ਤੁਹਾਡੇ ਫ਼ੋਨ ’ਤੇ ਹੀ ਰਹਿੰਦਾ ਹੈ।",
