  "On": "ਚਾਲੂ",
  "Off": "ਬੰਦ",
  "When you start work, swipe to start your shift. Every drive in it counts as {{purpose}}.": "ਕੰਮ ਸ਼ੁਰੂ ਕਰਦੇ ਸਮੇਂ ਸਵਾਈਪ ਕਰਕੇ ਸ਼ਿਫਟ ਸ਼ੁਰੂ ਕਰੋ। ਉਸ ਵਿੱਚ ਹਰ ਟ੍ਰਿਪ {{purpose}} ਗਿਣਿਆ ਜਾਵੇਗਾ।",
  "Drives in your hours ({{days}} {{from}}–{{to}}) are sorted as work for you.": "ਤੁਹਾਡੇ ਘੰਟਿਆਂ ({{days}} {{from}}–{{to}}) ਵਿੱਚ ਟ੍ਰਿਪ ਆਪਣੇ-ਆਪ ਕੰਮ ਵਿੱਚ ਪਾਏ ਜਾਂਦੇ ਹਨ।",
  "Drives in your work hours are sorted as work for you.": "ਤੁਹਾਡੇ ਕੰਮ ਦੇ ਘੰਟਿਆਂ ਵਿੱਚ ਟ੍ਰਿਪ ਆਪਣੇ-ਆਪ ਕੰਮ ਵਿੱਚ ਪਾਏ ਜਾਂਦੇ ਹਨ।",
  "After each drive, swipe right if it was for work (deliveries, pickups), left if it was personal.": "ਹਰ ਟ੍ਰਿਪ ਤੋਂ ਬਾਅਦ, ਕੰਮ ਦਾ ਹੋਵੇ (ਡਿਲੀਵਰੀ, ਪਿਕਅੱਪ) ਤਾਂ ਸੱਜੇ, ਨਿੱਜੀ ਹੋਵੇ ਤਾਂ ਖੱਬੇ ਸਵਾਈਪ ਕਰੋ।",
  "{{rate}} a mile · {{vehicle}} · {{country}}": "{{rate}} ਪ੍ਰਤੀ ਮੀਲ · {{vehicle}} · {{country}}",
  "{{rate}} a km · {{vehicle}} · {{country}}": "{{rate}} ਪ੍ਰਤੀ ਕਿ.ਮੀ. · {{vehicle}} · {{country}}",
  "PRACTICE RUN": "ਪ੍ਰੈਕਟਿਸ",
  "This is how a drive shows up after you park. Try sorting it.": "ਪਾਰਕ ਕਰਨ ਤੋਂ ਬਾਅਦ ਟ੍ਰਿਪ ਇੰਝ ਦਿਸਦਾ ਹੈ। ਇਸਨੂੰ ਛਾਂਟ ਕੇ ਦੇਖੋ।",
  "Swipe left if it was personal": "ਨਿੱਜੀ ਸੀ ਤਾਂ ਖੱਬੇ ਸਵਾਈਪ ਕਰੋ",
  "Not that way. Try again.": "ਉਸ ਪਾਸੇ ਨਹੀਂ। ਫਿਰ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "Sorted as personal ✓": "ਨਿੱਜੀ ਵਿੱਚ ਪਾਇਆ ✓",
  "Now a work drive. Work drives count at tax time.": "ਹੁਣ ਇੱਕ ਕੰਮ ਦਾ ਟ੍ਰਿਪ। ਟੈਕਸ ਵੇਲੇ ਕੰਮ ਦੇ ਟ੍ਰਿਪ ਗਿਣੇ ਜਾਂਦੇ ਹਨ।",
  "Now a delivery. Deliveries and pickups are work drives, and they count at tax time.": "ਹੁਣ ਇੱਕ ਡਿਲੀਵਰੀ। ਡਿਲੀਵਰੀ ਅਤੇ ਪਿਕਅੱਪ ਕੰਮ ਦੇ ਟ੍ਰਿਪ ਹਨ, ਅਤੇ ਟੈਕਸ ਵੇਲੇ ਇਹ ਗਿਣੇ ਜਾਂਦੇ ਹਨ।",
  "Swipe right if it was for work": "ਕੰਮ ਦਾ ਸੀ ਤਾਂ ਸੱਜੇ ਸਵਾਈਪ ਕਰੋ",
  "Sorted as work: worth {{amount}}": "ਕੰਮ ਵਿੱਚ ਪਾਇਆ: ਕੀਮਤ {{amount}}",
  "Swipe to start your shift": "ਆਪਣੀ ਸ਼ਿਫਟ ਸ਼ੁਰੂ ਕਰਨ ਲਈ ਸਵਾਈਪ ਕਰੋ",
  "Your shift is on ✓": "ਤੁਹਾਡੀ ਸ਼ਿਫਟ ਸ਼ੁਰੂ ਹੋ ਗਈ ✓",
  "Mark as personal": "ਨਿੱਜੀ ਮਾਰਕ ਕਰੋ",
