  "That’s it. Just drive: trips appear here after you park.": "ਬੱਸ ਇੰਨਾ ਹੀ। ਗੱਡੀ ਚਲਾਓ: ਪਾਰਕ ਕਰਨ ਤੋਂ ਬਾਅਦ ਟ੍ਰਿਪ ਇੱਥੇ ਦਿਸਣਗੇ।",
  "Ends the practice run": "ਅਭਿਆਸ ਖ਼ਤਮ ਕਰਦਾ ਹੈ",
  "Swipe to start driving": "ਗੱਡੀ ਚਲਾਉਣਾ ਸ਼ੁਰੂ ਕਰਨ ਲਈ ਸਵਾਈਪ",
  "Skip": "ਛੱਡੋ",
