  "Replay the tutorial": "ਟਿਊਟੋਰੀਅਲ ਫਿਰ ਦੇਖੋ",
  "Try sorting two sample drives again. Nothing is saved.": "ਦੋ ਨਮੂਨਾ ਟ੍ਰਿਪ ਫਿਰ ਛਾਂਟ ਕੇ ਦੇਖੋ। ਕੁਝ ਵੀ ਸੇਵ ਨਹੀਂ ਹੁੰਦਾ।",
  "Replay": "ਫਿਰ ਦੇਖੋ",
