  // The shift on the lock screen (Live Activity).
  "Show shift on lock screen": "ਲੌਕ ਸਕ੍ਰੀਨ ’ਤੇ ਸ਼ਿਫਟ ਦਿਖਾਓ",
  "You’ve driven {{distance}} for work today, worth about {{amount}}.": "ਅੱਜ ਤੁਸੀਂ ਕੰਮ ਲਈ {{distance}} ਡਰਾਈਵ ਕੀਤਾ, ਜੋ ਲਗਭਗ {{amount}} ਦੇ ਬਰਾਬਰ ਹੈ।",
  "You’ve driven {{distance}} for work this week, worth about {{amount}}.": "ਇਸ ਹਫ਼ਤੇ ਤੁਸੀਂ ਕੰਮ ਲਈ {{distance}} ਡਰਾਈਵ ਕੀਤਾ, ਜੋ ਲਗਭਗ {{amount}} ਦੇ ਬਰਾਬਰ ਹੈ।",
