  "It’s confirmed once iCloud can check it, and counts towards your friend’s perks.": "iCloud ਦੇ ਜਾਂਚਦੇ ਹੀ ਇਹ ਪੱਕਾ ਹੋ ਜਾਵੇਗਾ, ਅਤੇ ਤੁਹਾਡੇ ਦੋਸਤ ਦੇ ਫ਼ਾਇਦਿਆਂ ਵਿੱਚ ਗਿਣਿਆ ਜਾਵੇਗਾ।",
