  "Use my invite code {{code}} when you set up MileSprout and your first year of Pro is 50% off.": "MileSprout ਸੈੱਟ ਅੱਪ ਕਰਦੇ ਸਮੇਂ ਮੇਰਾ ਸੱਦਾ ਕੋਡ {{code}} ਭਰੋ, ਅਤੇ Pro ਦਾ ਤੁਹਾਡਾ ਪਹਿਲਾ ਸਾਲ 50% ਸਸਤਾ ਹੋਵੇਗਾ।",
  "Use my invite code {{code}} when you set up MileSprout.": "MileSprout ਸੈੱਟ ਅੱਪ ਕਰਦੇ ਸਮੇਂ ਮੇਰਾ ਸੱਦਾ ਕੋਡ {{code}} ਭਰੋ।",
  "I log my work miles with MileSprout. It tracks every drive by itself, free, with no account.": "ਮੇਰੇ ਕੰਮ ਦੇ ਮੀਲ MileSprout ਵਿੱਚ ਦਰਜ ਹੁੰਦੇ ਹਨ। ਇਹ ਹਰ ਟ੍ਰਿਪ ਆਪੇ ਰਿਕਾਰਡ ਕਰਦਾ ਹੈ, ਮੁਫ਼ਤ ਅਤੇ ਬਿਨਾਂ ਖਾਤੇ ਦੇ।",
  "I log my work kilometres with MileSprout. It tracks every drive by itself, free, with no account.": "ਮੇਰੇ ਕੰਮ ਦੇ ਕਿਲੋਮੀਟਰ MileSprout ਵਿੱਚ ਦਰਜ ਹੁੰਦੇ ਹਨ। ਇਹ ਹਰ ਟ੍ਰਿਪ ਆਪੇ ਰਿਕਾਰਡ ਕਰਦਾ ਹੈ, ਮੁਫ਼ਤ ਅਤੇ ਬਿਨਾਂ ਖਾਤੇ ਦੇ।",
