  "{{authority}} allows {{rate}} a km, so it adds up fast.": "{{authority}} ਪ੍ਰਤੀ km {{rate}} ਦਿੰਦਾ ਹੈ, ਇਸ ਲਈ ਰਕਮ ਤੇਜ਼ੀ ਨਾਲ ਵਧਦੀ ਹੈ।",
