  "See what each delivery app pays you, plus gold leaves on your sprout.": "ਦੇਖੋ ਹਰ ਡਿਲੀਵਰੀ ਐਪ ਤੁਹਾਨੂੰ ਕਿੰਨਾ ਦਿੰਦੀ ਹੈ, ਨਾਲ ਤੁਹਾਡੇ ਪੌਦੇ ’ਤੇ ਸੁਨਹਿਰੀ ਪੱਤੇ।",
